/bin/zsh -lc "python3 -c 'exec(\"\"\"import csv,json,math,itertools,pathlib,bisect
S=json.load(open(\"evaluation/pilot/witness-v4/specs-b.json\"))
def rd(p,n):
 with open(p/n,newline=\"\") as f:return list(csv.DictReader(f,delimiter=\"\\\\t\" if n.endswith(\"tsv\") else \",\"))
def bc(a,b):return sum(abs(x-y) for x,y in zip(a,b))/(sum(a)+sum(b))
def mean(v):return math.fsum(v)/len(v)
def mb(v):return mean([bc(a,b) for a,b in itertools.combinations(v,2)])
def rel(v):return [x/sum(v) for x in v]
def sh(v):return -math.fsum(x*math.log(x) for x in rel(v) if x)
def perm(v,g):
 n=len(v); size={x:g.count(x) for x in set(g)}; pairs=[(i,j,bc(v[i],v[j])**2) for i,j in itertools.combinations(range(n),2)]; t=math.fsum(d/n for i,j,d in pairs); w=math.fsum(d/size[g[i]] for i,j,d in pairs if g[i]==g[j]); a=len(size); return (t-w)/(a-1)/(w/(n-a)),(t-w)/t
def matrix(p):
 return {r[\"sample\"]:[float(v) for k,v in r.items() if k"'!="sample"] for r in rd(p,"counts.tsv")}
out=[]
for s in S:
 p=pathlib.Path(s["materials"]); typ=s["item"].split("/")[-1][:3]; z={}
 if typ=="P09":
  cat={r["specimen_id"]:r["individual_id"] for r in rd(p,"catalogue.csv")}; data={}
  for r in rd(p,"measurements.csv"):
   k=cat[r["specimen_id"]]; v=(float(r["length_mm"]),float(r["height_mm"])); assert k not in data or data[k]==v; data[k]=v
  x=[math.log10(v[0]) for v in data.values()]; y=[math.log10(v[1]) for v in data.values()]; mx=mean(x); my=mean(y); slope=math.copysign(math.sqrt(sum((v-my)**2 for v in y)/sum((v-mx)**2 for v in x)),sum((a-mx)*(b-my) for a,b in zip(x,y))); z={"n":len(x),"slope":slope,"intercept":my-slope*mx}
 elif typ=="P10":
  samples=sorted(rd(p,"samples.csv"),key=lambda r:float(r["depth_cm"])); v=matrix(p); z={"shannon_change":sh(v[samples[0]["sample_id"]])-sh(v[samples[-1]["sample_id"]])}
 elif typ=="P11":
  rows=rd(p,"counts.tsv"); tax={r["name_as_recorded"]:r["current_name"].split()[0] for r in rd(p,"taxonomy.csv")}; keys=[k for k in rows[0] if k!="taxon"]; data={g:[0]*len(keys) for g in set(tax[r["taxon"]] for r in rows)}
  for r in rows:
   v=data[tax[r["taxon"]]]
   for i,k in enumerate(keys):v[i]+=int(r[k])
  z={"mean_bray_curtis":mb(list(zip(*data.values()))),"n_genera":sum(sum(v)>0 for v in data.values())}
 elif typ=="P12":
  m=matrix(p); zones=rd(p,"zonation.csv"); v=[]; g=[]
  for r in rd(p,"samples.csv"):
   d=float(r["depth_cm"]); found=[x["zone"] for x in zones if float(x["top_cm"])<=d<float(x["base_cm"])]; assert len(found)==1
   if found[0] in ("A","B"):v.append(rel(m[r["sample_id"]])); g.append(found[0])
  f,r2=perm(v,g); z={"n":len(v),"pseudo_f":f,"r_squared":r2}
 elif typ=="P03":
  from decimal import Decimal,ROUND_HALF_EVEN
  meta={r["sample_id"]:r for r in rd(p,"samples.csv")}; v=[]
  for r in rd(p,"counts.tsv"):
   m=meta[r["sample"]]; vals=[Decimal(x) for k,x in r.items() if k!="sample"]
   if m["value_type"]=="relative (%)":vals=[(x*Decimal(m["n_counted"])/100).quantize(Decimal(1),rounding=ROUND_HALF_EVEN) for x in vals]
   v.append([float(x) for x in vals])
  z={"mean_bray_curtis":mb(v)}
 elif typ=="P04":
  cores=rd(p,"cores.csv"); picks=rd(p,"picking.csv"); both=all(any(x["core_id"]==r["core_id"] and x["fraction_um"]=="63-150" and x["status"]=="picked in full" for x in picks) for r in cores); hi=rd(p,"counts_gt150.tsv"); lo=rd(p,"counts_63_150.tsv") if both else []
  for campaign in ("2017","2021"):
   vals=[]
   for core in [r["core_id"] for r in cores if r["campaign"]==campaign]:
    lower={r["taxon"]:int(r[core]) for r in lo}; vals.append(sh([int(r[core])+lower.get(r["taxon"],0) for r in hi]))
   z["shannon_mean_"+campaign]=mean(vals)
 elif typ=="P05":
  tax={r["name_as_recorded"]:r["accepted_name"] for r in rd(p,"taxonomy.csv")}; rows=rd(p,"counts.tsv"); names=sorted(set(tax.values())); v=[]
  for r in rows:
   d=dict.fromkeys(names,0)
   for k,x in r.items():
    if k!="sample":d[tax[k]]+=int(x)
   v.append([d[n] for n in names])
  z={"mean_bray_curtis":mb(v),"richness":sum(sum(c)>0 for c in zip(*v))}
 elif typ=="P06":
  reg={r["lab_number"]:r["core_id"] for r in rd(p,"register.csv")}; zones={r["core_id"]:r["zone"] for r in rd(p,"cores.csv")}; data={}
  for r in rd(p,"counts.tsv"):
   k=reg[r["lab_number"]]; v=[int(x) for key,x in r.items() if key!="lab_number"]; data[k]=[a+b for a,b in zip(data.get(k,[0]*len(v)),v)]
  f,r2=perm([rel(v) for v in data.values()],[zones[k] for k in data]); z={"n":len(data),"pseudo_f":f,"r_squared":r2}
 elif typ=="P08":
  ds=sorted((float(r["depth_cm"]),float(r["age_cal_bp"])) for r in rd(p,"dates.csv") if r["status"]=="accepted"); m=matrix(p); v=[]
  for r in rd(p,"samples.csv"):
   d=float(r["depth_cm"]); i=max(0,min(len(ds)-2,bisect.bisect_right([x[0] for x in ds],d)-1)); (x,y),(xx,yy)=ds[i:i+2]; age=y+(d-x)*(yy-y)/(xx-x)
   if age<11700:v.append(rel(m[r["sample_id"]]))
  z={"n_holocene":len(v),"mean_bray_curtis":mb(v)}
 assert set(z)==set(s["report_fields"]); out.append({"item":s["item"],"results":[{"name":k,"value":z[k]} for k in s["report_fields"]],"notes":""})
print(json.dumps({"items":out},indent=2))
""")'"'"

